import React, { useState, useEffect } from 'react';
import './HeroSection.css';

function HeroSection({ onNavigate }) {
  const [currentSlide, setCurrentSlide] = useState(0);
  const slides = [
    {
      title: "Avatar: Dòng Chảy Của Nước",
      subtitle: "Khám phá thế giới Pandora đầy màu sắc",
      image: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?q=80&w=1200&auto=format&fit=crop",
      genre: "Viễn Tưởng",
      rating: "4.9/5 ⭐"
    },
    {
      title: "Lật Mặt 8: Sức Mạnh Tình Thân",
      subtitle: "Hành động hài kịch gia đình Việt Nam",
      image: "https://images.unsplash.com/photo-1536440136628-849c177e76a1?q=80&w=1200&auto=format&fit=crop",
      genre: "Hành Động",
      rating: "4.7/5 ⭐"
    },
    {
      title: "Doraemon: Bản Giao Hưởng Địa Cầu",
      subtitle: "Hành trình phim hoạt hình anime hấp dẫn",
      image: "https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?q=80&w=1200&auto=format&fit=crop",
      genre: "Hoạt Hình",
      rating: "4.8/5 ⭐"
    }
  ];

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slides.length);
    }, 5000);
    return () => clearInterval(timer);
  }, [slides.length]);

  const goToSlide = (index) => {
    setCurrentSlide(index);
  };

  return (
    <section className="hero-section">
      <div className="hero-slider">
        {slides.map((slide, index) => (
          <div
            key={index}
            className={`slide ${index === currentSlide ? 'active' : ''}`}
            style={{
              backgroundImage: `url(${slide.image})`
            }}
          >
            <div className="slide-overlay"></div>
            <div className="slide-content">
              <h1 className="slide-title">{slide.title}</h1>
              <p className="slide-subtitle">{slide.subtitle}</p>
              <div className="slide-info">
                <span className="slide-genre">{slide.genre}</span>
                <span className="slide-rating">{slide.rating}</span>
              </div>
              <div className="slide-actions">
                <button className="btn-watch" onClick={() => onNavigate('movies')}>▶ Xem Ngay</button>
                <button className="btn-details" onClick={() => onNavigate('genres')}>ℹ Thông Tin</button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Navigation Dots */}
      <div className="slider-dots">
        {slides.map((_, index) => (
          <button
            key={index}
            className={`dot ${index === currentSlide ? 'active' : ''}`}
            onClick={() => goToSlide(index)}
            aria-label={`Go to slide ${index + 1}`}
          ></button>
        ))}
      </div>

      {/* Navigation Arrows */}
      <button
        className="slider-arrow prev"
        onClick={() => setCurrentSlide((prev) => (prev - 1 + slides.length) % slides.length)}
      >
        ❮
      </button>
      <button
        className="slider-arrow next"
        onClick={() => setCurrentSlide((prev) => (prev + 1) % slides.length)}
      >
        ❯
      </button>
    </section>
  );
}

export default HeroSection;
